    private static readonly string[] Locales = ["es", "en", "fr", "it"];
    private static readonly Dictionary<string, string>[] Catalog = Enumerable.Range(0, Locales.Length)
        .Select(index => Rows.ToDictionary(row => row.Key, row => index switch
        {
            0 => row.Es, 1 => row.En, 2 => row.Fr, _ => row.It,
        }, StringComparer.Ordinal)).ToArray();

    public static IReadOnlyCollection<string> Keys => Catalog[0].Keys.Where(key => !IsHostKey(key)).ToArray();

    internal static bool ContainsKey(string key) => !IsHostKey(NormalizeKey(key))
        && Catalog[0].ContainsKey(NormalizeKey(key));

    internal static bool TryTranslate(string locale, string key, out string text)
    {
        var index = Array.IndexOf(Locales, locale);
        var normalizedKey = NormalizeKey(key);
        if (index >= 0 && !IsHostKey(normalizedKey)
            && Catalog[index].TryGetValue(normalizedKey, out text!)) return true;
        text = "";
        return false;
    }

    private static string NormalizeKey(string key) => key.StartsWith("worktree.", StringComparison.Ordinal)
        ? "cli." + key : key;

    private static bool IsHostKey(string key) => key.StartsWith("cli.maintenance.", StringComparison.Ordinal)
        || key.StartsWith("cli.journal.", StringComparison.Ordinal);
}
